import errno
import iopath.common.file_io as file_io

_orig_open = file_io.PathManager.open
_orig_mkdirs = file_io.PathManager.mkdirs
_orig_rm = file_io.PathManager.rm
_orig_symlink = file_io.PathManager.symlink

_blocked_substrings = [
    "/tmp/",
    "checkpoint",
    ".pkl",
    ".pth",
    "test_",
]

def _should_block_path(path: str) -> bool:
    if not path:
        return False
    for sub in _blocked_substrings:
        if sub in path:
            return True
    return False

def _patched_open(self, path, *args, **kwargs):
    if _should_block_path(path):
        raise PermissionError(errno.EPERM, "Operation not permitted (simulated)")
    return _orig_open(self, path, *args, **kwargs)

def _patched_mkdirs(self, path, *args, **kwargs):
    if _should_block_path(path):
        raise PermissionError(errno.EPERM, "Operation not permitted (simulated)")
    return _orig_mkdirs(self, path, *args, **kwargs)

def _patched_rm(self, path, *args, **kwargs):
    if _should_block_path(path):
        raise PermissionError(errno.EPERM, "Operation not permitted (simulated)")
    return _orig_rm(self, path, *args, **kwargs)

def _patched_symlink(self, src_path, dst_path, *args, **kwargs):
    if _should_block_path(src_path) or _should_block_path(dst_path):
        raise PermissionError(errno.EPERM, "Operation not permitted (simulated)")
    return _orig_symlink(self, src_path, dst_path, *args, **kwargs)

file_io.PathManager.open = _patched_open
file_io.PathManager.mkdirs = _patched_mkdirs
file_io.PathManager.rm = _patched_rm
file_io.PathManager.symlink = _patched_symlink
